package com.campus.secondhand.marketplace;
import java.util.*;
public final class SearchQueryRules { private SearchQueryRules(){} public static SearchQuery normalize(SearchQuery r){ if(r==null)throw new IllegalArgumentException("查询不能为空"); var scope=r.scope()==null?SearchQuery.Scope.ITEMS:r.scope(); var sort=r.sort()==null?SearchQuery.Sort.RELEVANCE:r.sort(); if(scope==SearchQuery.Scope.USERS&&(sort==SearchQuery.Sort.PRICE_ASC||sort==SearchQuery.Sort.PRICE_DESC))sort=SearchQuery.Sort.RELEVANCE; if(r.minPrice()!=null&&r.minPrice().signum()<0||r.maxPrice()!=null&&r.maxPrice().signum()<0)throw new IllegalArgumentException("价格不能小于 0"); if(r.minPrice()!=null&&r.maxPrice()!=null&&r.minPrice().compareTo(r.maxPrice())>0)throw new IllegalArgumentException("最低价格不能高于最高价格"); String region=r.region()==null||r.region().isBlank()?null:r.region().trim(); if(region!=null&&!MarketplaceOptions.REGIONS.contains(region))throw new IllegalArgumentException("区域无效"); Set<String> tags=r.tags()==null?Set.of():Set.copyOf(r.tags()); if(!MarketplaceOptions.TAGS.containsAll(tags))throw new IllegalArgumentException("标签无效"); return new SearchQuery(r.keywords(),scope,sort,r.minPrice(),r.maxPrice(),region,tags,r.sellerId(),Math.max(0,r.page()),Math.min(48,Math.max(1,r.size()))); } public static List<String> terms(String s){if(s==null||s.isBlank())return List.of();return Arrays.stream(s.trim().split("[\\s,，]+")).map(String::toLowerCase).distinct().limit(8).toList();} }
